/*! 注家分片 荀爽（集解 248 / 折中 5）*/
window.YJ_ZJ_ZJ = window.YJ_ZJ_ZJ || {};
window.YJ_ZJ_ZJ["zj_xunshuang"] = {"id":"zj_xunshuang","name":"荀爽","jijieQuotes":[{"gua":"乾","guaId":"g01","yaoIdx":2,"position":"九三：君子终日乾乾，夕惕，若厉，无咎。","text":"日以喻君。谓三居下体之终，而为之君，承乾行乾，故曰“乾乾”。夕惕以喻臣。谓三臣于五，则疾修柔顺，危去阳行，故曰“无咎”。","locator":{"book":"周易集解","gua":"乾","pos":"九三"},"citation":"《周易集解》·乾卦·九三","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":9,"position":"万物资始，","text":"谓分为六十四卦，万一千五百二十册，皆受始于乾也。册取始于乾，犹万物之生禀于天。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":12,"position":"大明终始，","text":"乾起坎，而终于离。坤起于离，而终于坎。离坎者，乾坤之家，而阴阳之府，故曰“大明终始”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":13,"position":"六位时成，","text":"六爻随时而成乾。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":19,"position":"潜龙勿用，阳在下也。","text":"气微位卑，虽有阳德，潜藏在下，故曰“勿用”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":20,"position":"见龙在田，德施普也。","text":"见者，见居其位。田，谓坤也。二当升坤五。故曰“见龙在田”。大人，谓天子。见据尊位，临长群阴，德施于下，故曰“德施普也”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":22,"position":"或跃在渊，进无咎也。","text":"乾者，君卦。四者，阴位。故上跃居五者，欲下居坤初，求阳之正。地下称渊也。阳道乐进，故曰“进无咎也”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":23,"position":"飞龙在天，大人造也。","text":"飞者，喻无所拘。天者，首事造制。大人造法，见居天位，圣人作为万物睹，是其义也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":29,"position":"利者，义之和也。","text":"阴阳相合，各得其宜，然后利矣。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":30,"position":"贞者，事之干也。","text":"阴阳正而位当，则可以干举万事。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":43,"position":"庸言之信，","text":"处和应坤，故曰“信”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":47,"position":"德博而化。","text":"处五据坤，故“德博”。群阴顺从，故物“化”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":51,"position":"修辞立其诚，所以居业也。","text":"修辞谓“终曰乾乾”。立诚，谓“夕惕若厉”。居业，谓“居三”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":57,"position":"九四曰：或跃在渊，无咎，何谓也？子曰：上","text":"乾者，君卦。四者，臣位也。故欲上跃。居五下者，当下居坤初，得阳正位。故曰：“上下无常，非为邪也”。","locator":{"book":"周易集解","gua":"乾","pos":"九四"},"citation":"《周易集解》·乾卦·九四","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":58,"position":"进退无恒，非离群也。","text":"进，谓居五。退，谓居初。故“进退无恒，非离群也”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":62,"position":"水流湿，","text":"阳动之坤而为坎，坤者纯阴，故曰“湿”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":63,"position":"火就燥。","text":"阴动之乾而成离，乾者纯阳，故曰：“燥”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":64,"position":"云从龙，","text":"龙，喻王者。谓乾二之坤五为坎也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":65,"position":"风从虎。","text":"虎，喻国君。谓坤五之乾二为巽，而从三也。三者，下体之君，故以喻国君。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":67,"position":"本乎天者亲上，","text":"谓乾九二，本出于乾，故曰“本乎天”。而居坤五，故曰“亲上”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":68,"position":"本乎地者亲下，","text":"谓坤六五，本出于坤，故曰：“本乎地”。降居乾二，故曰“亲下”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":70,"position":"上九曰：亢龙有悔，何谓也？子曰：贵而无位","text":"在上，故“贵”。失正，故“无位”。","locator":{"book":"周易集解","gua":"乾","pos":"上九"},"citation":"《周易集解》·乾卦·上九","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":72,"position":"贤人在下位，","text":"谓上应三，三阳德正，故曰“贤人”。别体在下，故曰“在下位”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":73,"position":"而无辅，","text":"两阳无应，故“无辅”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":74,"position":"是以动而有悔也。","text":"升极当降，故有“悔”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":96,"position":"以御天也。","text":"御者，行也。阳升阴降，天道行也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":97,"position":"云行雨施，天下平也。","text":"乾升于坤，曰“云行”。坤降于乾，曰“雨施”。乾坤二卦，成雨既济。阴阳和均，和而其正，故曰“天下平”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":100,"position":"潜之为言也，隐而未见，行而未成，是以君子","text":"“隐而未见”，谓居初也，“行而未成”，谓行之坤四。阳居阴位，未成为君。乾者，君卦也。不成为君，故不用也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":111,"position":"与天地合其德，","text":"与天合德，谓居五也。与地合德，谓居二也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":112,"position":"与日月合其明，","text":"谓坤五之乾二成离，离为日。乾二之坤五为坎，坎为月。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":118,"position":"天且弗违，况于人乎？","text":"人谓三。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":119,"position":"况于鬼神乎？","text":"神谓天，鬼谓地也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":120,"position":"亢之为言也，知进而不知退，","text":"阳位在五，今乃居上，故曰“知进而不知退”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":121,"position":"知存而不知亡，","text":"在上当阴，今反为阳，故曰“知存而不知亡”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":122,"position":"知得而不知丧，","text":"得谓阳，丧谓阴。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":124,"position":"其唯圣人乎！知进退存亡而不失其正者，其唯","text":"进谓居五。退谓居二。存谓五，为阳位。亡谓上，为阴位也。再出圣人者，上圣人谓五，下圣人谓二也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":3,"position":"万物资生，","text":"谓万一千五百二十策，皆受始于乾，由坤而生也。策生于坤，犹万物成形，出乎地也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":7,"position":"含宏光大，","text":"乾二居坤五为含，坤五居乾二为弘，坤初居乾四为光，乾四居坤初为大也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":8,"position":"品物咸亨。","text":"天地交，万物生，故“咸亨”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":21,"position":"六二：直方大。","text":"大者，阳也。二应五，五下动之，则应阳出，直布阳于四方。","locator":{"book":"周易集解","gua":"坤","pos":"六二"},"citation":"《周易集解》·坤卦·六二","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":22,"position":"不习无不利。","text":"物唱乃和，不敢先有所习。阳之所唱，从而和之，“无不利”也。干宝曰：阴气在二，六月之时，自遁来也。阴出地上，佐阳成物，臣道也，妻道也。臣之事君，妻之事夫，义成者也。臣贵其直，义尚其方，地体其大，故曰“直方大”。士该九德，然后可以从王事；女躬四教，然后可以配君子。道成于我，而用之于彼。不妨以仕举为政，不妨以嫁学为妇。故曰“不习无不利”也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":33,"position":"上六：龙战于野，","text":"消息之位，坤在于亥。下在伏乾，为其兼于阳，故称“龙”也。","locator":{"book":"周易集解","gua":"坤","pos":"上六"},"citation":"《周易集解》·坤卦·上六","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":39,"position":"坤至柔，","text":"纯阴至顺，故“柔”也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":41,"position":"至静而德方，","text":"坤性至静，得阳而动，布于四方也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":44,"position":"坤道其顺乎，承天而时行。","text":"承天之施，因四时而行之也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":50,"position":"：履霜，坚冰至，盖言顺也。","text":"霜者，乾之命令。坤下有伏乾，履霜坚冰，盖言顺也。乾气加之，性而坚，象臣顺君命而成之。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":53,"position":"直方大，不习，无不利，则不疑其所行也。","text":"直方大，乾之唱也。不习无不利，坤之和也。阳唱阴和，而无所不利，故“不疑其所行也”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":54,"position":"阴虽有美，含之，以从王事，弗敢成也。","text":"六三阳位，下有伏阳。坤阴卦也。虽有伏阳，含藏不显。以从王事，要待乾命，不敢自成也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":59,"position":"：括囊，无咎，无誉，盖言谨也。","text":"六四阴位，迫近于五，虽有成德，当括而囊之，谨慎畏敬也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":66,"position":"犹未离其类也，故称血焉。","text":"实本坤卦，故曰“未离其类也”。血以喻阴顺也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":67,"position":"夫玄黄者，天地之杂也。","text":"消息之卦，坤位在亥，下有伏乾，阴阳相和，故言“天地之杂也”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":68,"position":"天玄而地黄。","text":"天者阳，始于东北，故色玄也。地者阴，终于西南，故色黄也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":2,"position":"动乎险中，大亨贞。","text":"物难在始生，此本坎卦也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":3,"position":"雷雨之动满形，","text":"雷震雨润，则万物满形而生也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":4,"position":"天造草昧。","text":"谓阳动在下，造物于冥昧之中也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":5,"position":"宜建侯而不宁。","text":"天地初开，世尚屯难，震位承乾，故“宜建侯”。动而遇险，故“不宁”也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":7,"position":"君子以经论。","text":"屯难之代，万事失正。经者，常驻也。论者，理也。君子以经论，不失常道也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":9,"position":"：虽盘桓，志行正也。","text":"盘桓者，动而退也。顿谓从二动，而退居初，虽盘桓，得其正也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":10,"position":"以贵下贱，大得民也。","text":"阳贵而阴贱，阳从二来，是以贵下贱，所以得民也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":11,"position":"六二：屯如邅如，","text":"阳动而止，故“屯如”也。阴乘于阳，故“邅如”也，","locator":{"book":"周易集解","gua":"屯","pos":"六二"},"citation":"《周易集解》·屯卦·六二","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":4,"position":"蒙亨，以亨行时中也。","text":"此本艮卦也。案：二进居三，三降居二。刚柔得中，故能通。发蒙时，令得进中矣。故曰“蒙亨，以亨行时中也”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":6,"position":"童蒙求我，志应也。","text":"二与五志相应也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":8,"position":"再三渎，渎则不告，渎蒙也。","text":"再三，谓三与四也。皆乘阳，不敬，故曰“渎”。渎不能尊阳，蒙气不除，故曰“渎蒙也”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":19,"position":"：童蒙之吉，顺以巽也。","text":"顺于上，巽于二，有似成王任用周召也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":10,"position":"：需于沙，衍在中也。","text":"二应于五，水中之刚，故曰“沙”。知前有沙漠。而不进也。体乾处和，美德优衍在中，而不进也。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":11,"position":"虽小有言，以吉终也。","text":"二与四同功，而三据之，故“小有言”。乾虽在下，终当升上，二当居五，故“终吉也”。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":12,"position":"九三：需于泥，致寇至。","text":"亲与坎接，故称“泥”。须止不进，不取于四，不致寇害。","locator":{"book":"周易集解","gua":"需","pos":"九三"},"citation":"《周易集解》·需卦·九三","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":17,"position":"九五：需于酒食，贞吉。","text":"五互离，坎水在火上，酒食之象。需者，饮食之道。故坎在需家，为酒食也。云须时欲降，乾须时当升。五有刚德，处中居正。故能帅群阴，举坎以降。阳能正居其所，则吉。故曰“需于酒食”也。","locator":{"book":"周易集解","gua":"需","pos":"九五"},"citation":"《周易集解》·需卦·九五","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":19,"position":"上六：入于穴，","text":"需道已终，云当下入穴也。云上升极，则降而为雨，故《诗》云：朝跻于西，崇朝其雨，则还入地，故曰“入于穴”。云雨入地，则下三阳动而自至者也。","locator":{"book":"周易集解","gua":"需","pos":"上六"},"citation":"《周易集解》·需卦·上六","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":20,"position":"有不速之客三人来，敬之终吉。","text":"三人，谓下三阳也。须时当升，非有召者，故曰“不速之客”焉。乾升在上，君位以定；坎降在下，当循臣职。故“敬之终吉”也。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":21,"position":"：不速之客来，敬之终吉。虽不当位，未大失","text":"上降居三，虽不当位，承阳有实，故“终吉”，无“大失”矣。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":-1,"position":"卦辞","text":"阳来居二，而孚于初，故曰“讼有孚”矣。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞"},"citation":"《周易集解》·讼卦·卦辞","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":6,"position":"利见大人，尚中正也。","text":"二与四讼，利见于五。五以中正之道，解其讼也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":7,"position":"不利涉大川，入于渊也。","text":"阳来居二，坎在下，为渊。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":8,"position":"：天与水违行，讼。","text":"天自西转，水自东流，上下违行，成讼之象也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":14,"position":"：不克讼，归逋窜也。","text":"三不克讼，故逋而归。坤称邑。二者，邑中之阳人。逋，逃也，谓逃失邑中之阳人。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":15,"position":"自下讼上，患至掇也。","text":"下与上争，即取患害，如拾掇小物而不失也。坤有三爻，故云“三百户，无眚”。二者，下体之君。君不争，则百姓无害也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":23,"position":"终朝三拕之。","text":"二四争三，三本下体，取之有缘。或者，疑之辞也。以三锡二，于义疑矣。争竞争之世，分理未明，故或以锡二。终朝者，君道明。三者，阳成功也。君明道盛，则夺二与四，故曰“终朝三拕之”也。鞶带，宗庙之服。三应于上，上为宗庙。故曰“鞶带”也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":0,"position":"：师，众也。贞，正也。能以众正，可以王矣","text":"谓二有中和之德，而据群阴，上居五位，可以王也。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":8,"position":"王三锡命，怀万邦也。","text":"王谓二也。三者，阳德成也。德纯道盛，故能上居王位，而行锡命，群阴归之。故曰“王三锡命，怀万邦也”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":11,"position":"六四：师左次，无咎。","text":"左谓二也，阳称左。次，舍也。二与四同功，四承五，五无阳，故呼二舍于五，四得承之，故“无咎”。","locator":{"book":"周易集解","gua":"师","pos":"六四"},"citation":"《周易集解》·师卦·六四","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":13,"position":"六五：田有禽，利执言，无咎。","text":"田，猎也。谓二帅师禽五，五利度二之命，执行其言，故“无咎”也。","locator":{"book":"周易集解","gua":"师","pos":"六五"},"citation":"《周易集解》·师卦·六五","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":16,"position":"：长子帅师，以中行也。","text":"长子谓九二也。五处中应二，二受任帅师，当上升五。故曰“长子帅师，以中行也”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":19,"position":"开国承家，","text":"大君，谓二。师旅已息，既上居五，当封赏有功，立国命家也。开国，封诸侯。承家，立大夫也。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":5,"position":"其道穷也。","text":"后夫谓上六。逆礼乘阳，不比圣王，其义当诛，故“其道穷凶”也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":8,"position":"初六：有孚比之，无咎。","text":"初在应外，以喻殊俗，圣王之信，光被四表。绝域殊俗，皆来亲比，故“无咎”也。","locator":{"book":"周易集解","gua":"比","pos":"初六"},"citation":"《周易集解》·比卦·初六","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":10,"position":"：比之初六，有它吉也。","text":"缶者应内，以喻中国。孚既盈满中国，终来及初，非应，故曰“它”也。《象》云：“有它吉”者，谓信及非应，然后吉也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":23,"position":"上六：比之无首，凶。","text":"阳欲无首，阴以大终。阴而无首，不以大终。故“凶”也。","locator":{"book":"周易集解","gua":"比","pos":"上六"},"citation":"《周易集解》·比卦·上六","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":4,"position":"自我西郊，施未行也。","text":"体兑位秋，故曰“西郊”也。时当收敛，臣不专赏，故“施未行”。喻文王也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":14,"position":"：有孚惕出，上合志也。","text":"血以喻阴。四阴，臣象。有信顺五。惕，疾也。四当去初，疾出从五，故曰“上合志也”。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":0,"position":"：履，柔履刚也。","text":"谓三履二也。二五无应，故无元。以乾履兑，故有通。六三履二非和正，故云“利贞”也。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":6,"position":"：素履之往，独行愿也。","text":"初九者，潜位。隐而未见，行而未成。素履者，谓布衣之士，未得居位，独行礼义，不失其正，故“无咎也”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":6,"position":"：天地交泰，","text":"坤气上升，以成天道。乾气下降，以成地道。天地二气，若时不交，则为闭塞。今既相交，乃通泰。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":12,"position":"用冯河，不遐遗。","text":"河出于乾，行于地中。阳性欲升，阴性欲承。冯河而上，不用舟航。自地升天，道虽辽远，三体俱上，不能止之，故曰“不遐遗”。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":13,"position":"朋亡，得尚于中行。","text":"中，谓五。坤为朋，朋亡而下，则二上居五，而行中和矣。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":8,"position":"初六：拔茅茹以其汇，贞吉，亨。","text":"拔茅茹，取其相连，汇者，类也。合体同包，调坤三爻同类相连，欲在下也。贞者，正也。谓正居其所则“吉”也。","locator":{"book":"周易集解","gua":"否","pos":"初六"},"citation":"《周易集解》·否卦·初六","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":10,"position":"六二：包承，小人吉，大人否，亨。","text":"二与四同功，为四所包，故曰“包承”也。小人，二也。谓一爻独居，间象相承，得系于阳，故“吉”也。大人，谓五。乾坤分体，天地否隔，故曰“大人否”也。二五相应，否义得通，故曰“否，亨”矣。","locator":{"book":"周易集解","gua":"否","pos":"六二"},"citation":"《周易集解》·否卦·六二","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":12,"position":"六三：包羞。《象》曰：包羞，位不当也。","text":"卦性为否，其义否隔。今以不正，与阳相承，为四所包，违义失正，而可羞者，以“位不当”故也。","locator":{"book":"周易集解","gua":"否","pos":"六三"},"citation":"《周易集解》·否卦·六三","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":14,"position":"：有命无咎，志行也。","text":"谓志行于群阴也。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":16,"position":"其亡其亡，","text":"阴欲消阳，由四及五，故曰“其亡其亡”。谓坤性顺从，不能消乾使亡。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":17,"position":"系于包桑。","text":"包者，乾坤相包也。桑者，上玄下黄，以象乾坤也。乾职在上，坤体在下，虽欲消乾，系其本体，不能亡也。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":5,"position":"：天与火，同人。","text":"乾舍于离，相与同居，故曰“同人”也。","locator":{"book":"周易集解","gua":"同人","pos":"卦辞·彖象"},"citation":"《周易集解》·同人卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":9,"position":"六二：同人于宗，吝。","text":"宗者，众也。三据二阴，二与四同功，五相应，初相近，上下众阳，皆欲与二为同，故曰“同人于宗”也。阴道贞静，从一而终，今宗同之，故“吝”也。","locator":{"book":"周易集解","gua":"同人","pos":"六二"},"citation":"《周易集解》·同人卦·六二","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":2,"position":"：火在天上，大有。","text":"谓夏，火王在天，万物并生，故曰“大有”也。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":2,"position":"天道下济而光明，","text":"乾来之坤，故“下济”。阴去为离，阳来成坎，日月之象，故“光明”也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":12,"position":"初六：谦谦君子，用涉大川，吉。","text":"初最在下，为谦。二阴承阳，亦为谦。故曰“谦谦”也。二阴一阳，相与成体，故曰“君子”也。九三体坎，故“用涉大川，吉”也。","locator":{"book":"周易集解","gua":"谦","pos":"初六"},"citation":"《周易集解》·谦卦·初六","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":16,"position":"九三：劳谦，君子有终，吉。","text":"体坎为劳，终下二阴，君子有终，故“吉”也。","locator":{"book":"周易集解","gua":"谦","pos":"九三"},"citation":"《周易集解》·谦卦·九三","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":17,"position":"：劳谦君子，万民服也。","text":"阳光居五，自卑下众，降居下体，君有下国之意也。众阴皆欲捴阳上居五位，群阴顺阳，故“万民服也”。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":18,"position":"六四：无不利，捴谦。","text":"四得位处正，家性为谦，故“无不利”。阴欲捴三，使上居五，故曰“捴谦”。捴，犹举也。","locator":{"book":"周易集解","gua":"谦","pos":"六四"},"citation":"《周易集解》·谦卦·六四","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":20,"position":"六五：不富以其邻，","text":"邻谓四与上也。自四以上乘阳，乘阳失实，故皆不富，五居中有体，故总言之。","locator":{"book":"周易集解","gua":"谦","pos":"六五"},"citation":"《周易集解》·谦卦·六五","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":21,"position":"利用侵伐，无不利。","text":"谓阳利侵伐来上，无敢不利之者。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":22,"position":"：利用侵伐，征不服也。","text":"不服，谓五也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":22,"position":"：冥豫在上，何可长也？","text":"阳性冥昧，居尊在上，而犹豫说，故不可长。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":1,"position":"大亨贞，无咎。","text":"随者，震之归魂。震归从巽，故大通。动爻得正，故利贞。阳降阴升，嫌于有咎。动而得正，故“无咎”。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":4,"position":"蛊元亨，而天下治也。","text":"蛊者，巽也。巽归合震，故“元亨”也。蛊者，事也。备物致用，故“天下治”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":15,"position":"六五：干父之蛊，用誉。","text":"体和应中，承阳有实，用斯干事，荣誉之道也。","locator":{"book":"周易集解","gua":"蛊","pos":"六五"},"citation":"《周易集解》·蛊卦·六五","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":19,"position":"：不事王侯，志可则也。","text":"年老事终，不当其位。体艮为止。故“不事王侯”。据上临下，重阴累实，故“志可则”。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":4,"position":"：泽上有地，临。","text":"泽卑地高，高下相临之象也。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":7,"position":"：咸临贞吉，志行正也。","text":"阳始咸升，以刚临柔。得其正位而居，是吉。故曰：“志行正”。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":9,"position":"：咸临吉，无不利，未顺命也。","text":"阳感至二，当升居五，群阴相承，故“无不利”也。阳当居五，阴当顺从，今尚在二，故曰“未顺命也”。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":12,"position":"：至临无咎，位当也。","text":"四与二同功，欲升二至五，已得承顺之，故曰“至临”也。阳虽未乘，处位居正，故得“无咎”。是位当也。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":13,"position":"六五：知临，大君之宜，吉。《象》曰：大君","text":"五者，帝位。大君，谓二也。宜升上居五位，吉。故曰“知临，大君之宜”也。二者处中，行升居五，五亦处中，故曰“行中之谓也”。","locator":{"book":"周易集解","gua":"临","pos":"六五"},"citation":"《周易集解》·临卦·六五","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":14,"position":"上六：敦临，吉，无咎。","text":"上应于三，欲因三升二，过应于阳，敦厚之意，故曰：“敦临吉无咎”。","locator":{"book":"周易集解","gua":"临","pos":"上六"},"citation":"《周易集解》·临卦·上六","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":11,"position":"：观我生进退，未失道也。","text":"我，谓五也。生者，教化生也。三欲进观于五，四既在前，而三故退，未失道也。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":11,"position":"：遇毒，位不当也。","text":"昔肉，谓四也。三以不正，噬取异家，法当遇罪，故曰“遇毒”。为艮所止，所欲不得，故“小吝”也。所欲不得，则免于罪，故“无咎”矣。","locator":{"book":"周易集解","gua":"噬嗑","pos":"卦辞·彖象"},"citation":"《周易集解》·噬嗑卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":14,"position":"：贞厉无咎，得当也。","text":"谓阴来正居，是而厉阳也。以阴厉阳，正居其处。而无咎者，以从下升上，不失其中。所言得当。","locator":{"book":"周易集解","gua":"噬嗑","pos":"卦辞·彖象"},"citation":"《周易集解》·噬嗑卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":15,"position":"上九：何校灭耳，凶。","text":"为五所何，故曰“何校”。据五应三，欲尽灭坎。上体坎，为耳。故曰“灭耳凶”。上以不正，侵欲无已，夺取异家，恶积而不可掩，罪大而不可解，故“宜凶”矣。","locator":{"book":"周易集解","gua":"噬嗑","pos":"上九"},"citation":"《周易集解》·噬嗑卦·上九","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":1,"position":"：贲亨，柔来而文刚，故亨。分刚上而文柔，","text":"此本泰卦。谓阴从上来，居乾之中，文饰刚道，交于中和，故“亨”也。分乾之二，居坤之上，上饰柔道，兼据二阴故“小利有攸往”矣。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":17,"position":"：六五之吉，有喜也。","text":"艮，山。震，林。失其正位，在山林之间，贲饰邱陵，以为园圃，隐士之象也。五为王位，体中履和，勤贤之主，尊道之君也。故曰“贲于邱园，束帛戋戋”。君臣失正，故“吝”。能以中和饰上成功，故“终吉”而“有喜也”。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":1,"position":"柔变刚也。","text":"谓阴外变五。五者至尊，为阴所变，故曰“剥也”。","locator":{"book":"周易集解","gua":"剥","pos":"卦辞·彖象"},"citation":"《周易集解》·剥卦·卦辞·彖象","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":11,"position":"六三：剥无咎。《象》曰：剥之无咎，失上下","text":"众皆剥阳，三独应上，无剥害意，是以“无咎”。《象》曰：失上下也。","locator":{"book":"周易集解","gua":"剥","pos":"六三"},"citation":"《周易集解》·剥卦·六三","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":7,"position":"利有攸往，刚长也。","text":"利往居五，刚道浸长也。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":18,"position":"用行师，终有大败，以其国君凶，","text":"坤为众，故“用行师”也。谓上行师，而距于初。阳息上升，必消群阴，故“终有大败”。国君，谓初也。受命复道，当从下升。今上六行师，王诛必加。故“以其国君凶”也。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":10,"position":"君子以慎言语，节饮食。","text":"雷为号令，今在山下闭藏，故“慎言语”。雷动于上，以阳食阴，艮以止之，故“节饮食”也。言出乎身，加乎民，故慎言语所以养人也。饮食不节，残贼群生，故节饮食以养物。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":3,"position":"水流而不盈，","text":"阳动阴中，故“流”。阳陷阴中，故“不盈”也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":4,"position":"行险而不失其信。","text":"谓阳来为险，而不失中。中称信也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":15,"position":"：求小得，未出中也。","text":"处中而比初三，未足为援。虽求小得，未出于险中。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":1,"position":"：离，丽也。","text":"阴丽于阳，相附丽也。亦为别离，以阴隔阳也。离者，火也。托于木，是其附丽也。烟焰飞升，炭灰降滞，是其别离也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":6,"position":"是以畜牝牛吉也。","text":"牛者，土也。生土于火。离者，阴卦。牝者，阴性，故曰“畜牝牛吉”矣。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":9,"position":"初九：履错然，敬之，无咎。","text":"火性炎上，故初欲履错于二。二为三所据。故“敬之”则“无咎”矣。","locator":{"book":"周易集解","gua":"离","pos":"初九"},"citation":"《周易集解》·离卦·初九","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":12,"position":"九三：日昃之离，","text":"初为日出，三为日昃，以喻君道衰也。","locator":{"book":"周易集解","gua":"离","pos":"九三"},"citation":"《周易集解》·离卦·九三","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":15,"position":"九四：突如，其来如，焚如，死如，弃如。","text":"阳升居五，光炎宣扬，故“突如”也。阴退居四，灰炭降坠，故“其来如”也。阴以不正，居尊乘阳。历尽数终，天命所诛。位丧民畔，下离所害。故“焚如”也。以离入坎，故“死如”也。火息灰损，故“弃如”也。","locator":{"book":"周易集解","gua":"离","pos":"九四"},"citation":"《周易集解》·离卦·九四","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":17,"position":"六五：出涕沱若，","text":"六五阴柔，退居于四，出离为坎，故“出涕沱若”。而下，以顺阴阳也。","locator":{"book":"周易集解","gua":"离","pos":"六五"},"citation":"《周易集解》·离卦·六五","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":2,"position":"天地感而万物化生，","text":"乾下感坤，故万物化生于山泽。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":4,"position":"恒亨，无咎，利贞，久于其道也。","text":"恒，震世也，巽来乘之，阴阳合会，故“通无咎”。长男在上，长女在下，夫妇道正，故“利贞，久于其道也”。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":6,"position":"利有攸往，终则有始也。","text":"谓乾气下终，始复升上居四也。坤气上终，始复降下居初者也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":16,"position":"：九二悔亡，能久中也。","text":"乾为久也。能久行中和，以阳据阴，故曰“能久中也”。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":17,"position":"九三：不恒其德，或承之羞，贞吝。","text":"与初同象，欲据初，隔二。与五为兑，欲悦之，隔四。意无所定，故“不恒其德”。与上相应，欲往承之，为阴所乘，故“或承之羞”也。贞吝者，谓正居其所，不与阴通也。无居自容，故“贞吝”矣。","locator":{"book":"周易集解","gua":"恒","pos":"九三"},"citation":"《周易集解》·恒卦·九三","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":3,"position":"小利贞，浸而长也。","text":"阴称小，浸而长，则将消阳，故“利正”。居二与五相应也。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":13,"position":"畜臣妾吉，不可大事也。","text":"大事谓与五同任天下之政。潜遁之世，但可居家畜养臣妾，不可治国之大事。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":1,"position":"刚以动，故壮。","text":"乾刚震动，阳从下升，阳气大动，“故壮”也。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":10,"position":"羝羊触藩，羸其角。","text":"三与五同功，为兑，故曰“羊”。终始阳位，故曰“羝”。藩，谓四也。三欲触四而危之，四反羸其角。角，谓五也。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":2,"position":"是以康侯用锡马蕃庶。","text":"阴进居五，处用事之位。阳中之阴，侯之象也；阴性安静，故曰“康侯”。马，谓四也。五以下，群阴锡四也。坤为众，故曰“蕃庶”矣。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":15,"position":"六五：悔亡，矢得勿恤，往吉，无不利。","text":"五从坤动而来为离。离者，射也。故曰“矢得”。阴居尊位，故有悔也。以中盛明，光照四海，故“悔亡勿恤，吉无不利”也。","locator":{"book":"周易集解","gua":"晋","pos":"六五"},"citation":"《周易集解》·晋卦·六五","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":19,"position":"：惟用伐邑，道未光也。","text":"阳虽在上，动入冥豫，故道未光也。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":2,"position":"内文明而外柔顺，以蒙大难，","text":"明在地下，为坤所蔽，大难之象。大难，文王君臣相事，故言大难也。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":6,"position":"初九：明夷于飞，垂其翼。君子于行，三日不","text":"火性炎上，离为飞鸟，故曰“于飞”。为坤所抑，故曰“垂其翼”。阳为君子。三者，阳德成也。日以喻君。不食者，不得食君禄也。阳未居五，阴暗在上。初有明德，耻食其禄，故曰“君子于行，三日不食”也。","locator":{"book":"周易集解","gua":"明夷","pos":"初九"},"citation":"《周易集解》·明夷卦·初九","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":8,"position":"：君子于行，义不食也。","text":"暗昧在上，有明德者，义不食禄也。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":13,"position":"六四：入于左腹，获明夷之心，于出门庭。","text":"阳称左，谓九三也。腹者，谓五居坤，坤为腹也。四得位比三，应于顺首。欲上三居五，以阳为腹心也。故曰“入于左腹，获明夷之心”。言三当出门庭，升五君位。","locator":{"book":"周易集解","gua":"明夷","pos":"六四"},"citation":"《周易集解》·明夷卦·六四","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":2,"position":"家人有严君焉，父母之谓也。","text":"离巽之中有乾坤，故曰“父母之谓也”。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":5,"position":"而家道正。正家而天下定矣。","text":"父谓五，子谓四，兄谓三，弟谓初，夫谓五，妇谓二也。各得其正，故“天下定矣”。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":7,"position":"君子以言有物而行有恒。","text":"风火相与，必附于物。物大火大，物小火校君子之言，必因其位。位大言大，位小言校不在其位，不谋其政，故“言有物”也。大暑烁金，火不增其烈；大寒凝冰，火不损其热，故曰“行有恒”矣。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":8,"position":"初九：闲有家，悔亡。《象》曰：闲有家，志","text":"初在潜位，未干国政，闲习家事而已。未得治官，故“悔”。居家理治，可移于官，守之以正，故“悔亡”。而未变从国之事，故曰“志未变也”。","locator":{"book":"周易集解","gua":"家人","pos":"初九"},"citation":"《周易集解》·家人卦·初九","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":9,"position":"六二：无攸遂，在中馈，贞吉。","text":"六二处和得正。得正有应，有应有实，阴道之至美者也。坤道顺从，故无所得遂。供肴中馈，洒食是议，故曰“中辣。居中守正，永贞其志，则“吉”，故曰“贞吉”也。","locator":{"book":"周易集解","gua":"家人","pos":"六二"},"citation":"《周易集解》·家人卦·六二","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":3,"position":"是以小事吉。","text":"小事者，臣事也。百官异体，四民殊业，故睽而不同。刚者，君也。柔得其中，而应于君，故言“小事吉也”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":8,"position":"：上火下泽，睽。","text":"火性炎上，泽性润下，故曰“睽”也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":9,"position":"君子以同而异。","text":"大归虽同，小事当异。百家殊职，四民异业。文武并用，威德相反，共归于治，故曰“君子以同而异”也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":4,"position":"蹇利西南，往得中也。","text":"西南谓坤。乾动往居坤五，故“得中也”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":5,"position":"不利东北，其道穷也。","text":"东北，艮也。艮在坎下。见险而止，故“其道穷也”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":7,"position":"当位贞吉，以正邦也。","text":"谓五当尊位。正居是，群阴顺从，故能“正邦国”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":18,"position":"：往蹇来连，当位实也。","text":"蹇难之世，不安其所。欲往之三，不得承阳。故曰“往蹇”也。来还承五，则与至尊相连，故曰“来连”也。处正承阳，故曰“当位实也”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":3,"position":"解利西南，往得众也。","text":"乾动之坤而得众，西南众之象也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":4,"position":"无所往，","text":"阴处尊位，阳无所往也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":5,"position":"其来复吉，乃得中也。","text":"来复居二，处中成险，故曰“复吉”也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":6,"position":"有攸往，夙吉，往有功也。","text":"五位无君，二阳又卑，往居之者则吉。据五解难，故“有功也”。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":7,"position":"天地解而雷雨作，","text":"谓乾坤交通，动而成解卦，坎下震上，故“雷雨作”也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":8,"position":"雷雨作而百果草木皆甲宅。","text":"解者，震世也。仲春之月，草木萌牙。雷以动之，雨以润之，曰以烜之，故“甲宅”也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":3,"position":"损而有孚，","text":"谓损乾之三居上。孚，二阴也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":4,"position":"元吉，无咎。","text":"居上据阴，故“元吉，无咎”，以未得位，嫌于咎也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":5,"position":"可贞。","text":"少男在上，少女虽年尚幼，必当相承，故曰“可贞”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":6,"position":"利有攸往。","text":"谓阳利往居上。损者，损下益上，故利往居上。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":7,"position":"曷之用？二簋可用享。","text":"二簋，谓上体二阴也。上为宗庙。簋者，宗庙之器，故可享献也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":6,"position":"孚号有厉，其危乃光也。","text":"信其号令天下，众阳危。去上六，阳乃光明也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":8,"position":"不利即戎，所尚乃穷也。","text":"不利即尚兵戎，而与阳争，必困穷。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":17,"position":"君子夬夬，独行遇雨。","text":"九三体乾，乾为君子。三五同功，二爻俱欲决上，故曰“君子夬夬”也。“独行”谓一爻独上，与阴相应，为阴所施，兑为雨泽，故遇雨也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":18,"position":"若濡有愠，无咎。","text":"虽为阴所濡，能愠不悦，得无咎也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":23,"position":"九五：苋陆夬夬，","text":"苋谓五，陆谓三。两爻决上，故曰“夬夬”也。苋者，叶柔而根坚且赤，以言阴在上六也。陆亦取叶柔根坚也。去阴远，故言“陆”。言差坚于苋。苋根小，陆根大。五体兑，柔居上，苋也。三体乾，刚在下，根深，故谓之“陆”也。","locator":{"book":"周易集解","gua":"夬","pos":"九五"},"citation":"《周易集解》·夬卦·九五","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":3,"position":"天地相遇，品物咸章也。","text":"谓乾成于巽，而舍于离。坤出于离，与乾相遇，南方夏位，万物章明也。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":2,"position":"：萃，聚也，顺以说，刚中而应，故聚也。","text":"谓五以刚居中，群阴顺悦而从之，故能聚众也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":9,"position":"：泽上于地，萃。","text":"泽者卑下，流潦归之，万物生焉，故谓之萃也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":23,"position":"：赍资涕洟，未安上也。","text":"此本否卦。上九阳爻，见灭迁移，以喻夏桀殷纣。以上六阴爻代之，若夏之后封东娄公于杞，殷之后封微子于宋，去其骨肉，臣服异姓，受人封土，未安居位，故曰“赍资涕洟，未安上也”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":4,"position":"巽而顺，刚中而应，是以大亨。","text":"谓二以刚居中，而来应五，故能“大亨”。上居尊位也。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":5,"position":"用见大人勿恤，有庆也。","text":"大人，天子，谓升居五。见为大人，群阴有主，无所复忧，而有庆也。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":7,"position":"：地中生木，升。","text":"地谓坤。木谓巽。地中生木，以微至着，升之象也。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":9,"position":"初六：允升，大吉。","text":"谓一体相随，允然俱升。初欲与巽一体，升居坤上，位尊得正，故“大吉”也。","locator":{"book":"周易集解","gua":"升","pos":"初六"},"citation":"《周易集解》·升卦·初六","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":13,"position":"九三：升虚邑。","text":"坤称邑也。五虚无君，利二上居之，故曰“升虚邑，无所疑也”。","locator":{"book":"周易集解","gua":"升","pos":"九三"},"citation":"《周易集解》·升卦·九三","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":15,"position":"六四：王用享于岐山，吉，无咎。","text":"此本升卦也。巽升坤上，据三成艮。巽为歧，艮为山。王，谓五也。通有两体，位正众服，故“吉”也。四能与众阴退避当升者，故“无咎”也。","locator":{"book":"周易集解","gua":"升","pos":"六四"},"citation":"《周易集解》·升卦·六四","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":18,"position":"：贞吉升阶，大得志也。","text":"阴正居中，为阳作阶，使升居五，已下降二，与阳相应，故“吉而得志”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":19,"position":"上六：冥升，利于不息之贞。","text":"坤性暗昧，今升在上，故曰“冥升”也。阴用事，为消。阳用事，为息，阴正在上，阳道不息，阴之所利，故曰“利于不息之贞”。","locator":{"book":"周易集解","gua":"升","pos":"上六"},"citation":"《周易集解》·升卦·上六","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":20,"position":"：冥升在上，消不富也。","text":"阴升失实，故“消不富也”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":3,"position":"：困，刚弇也。","text":"谓二五为阴所弇也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":4,"position":"险以说，","text":"此本否卦。阳降为“险”，阴升为“说”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":5,"position":"困而不失其所亨，其唯君子乎？","text":"谓二虽弇阴陷险，犹不失中，与正阴合，故通也。喻君子虽陷险中，不失中和之行也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":6,"position":"贞大人吉，以刚中也。","text":"谓五虽弇于阴，近无所据，远无所应，体刚得中，正居五位，则“吉无咎”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":7,"position":"有言不信，尚口乃穷也。","text":"阴从二升上六，成兑。为有言。失中，为不信。动而乘阳，故曰“尚口乃穷也”。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":12,"position":"：入于幽谷，幽不明也。","text":"为阴所弇，故“不明”。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":14,"position":"利用享祀，征凶。无咎。","text":"二升在庙，五亲奉之，故“利用享祀”。阴动而上，失中乘阳；阳下而陷，为阴所弇，故曰“征凶”。阳降来二，虽位不正，得中有实；阴虽去中，上得居正，而皆免咎，故曰“无咎”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":28,"position":"利用祭祀，受福也。","text":"谓五爻合同，据国当位，而主祭祀，故“受福也”。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":4,"position":"：巽乎水而上水，井。","text":"巽乎水，谓阴下为巽也。而上水，谓阳上为坎也。木入水出，井之象也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":6,"position":"改邑不改井，乃以刚中也。","text":"刚得中，故为“改邑”。柔不得中，故为“不改井”也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":7,"position":"无丧无得。","text":"阴来居初，有实，为“无丧”。失中，为“无得”也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":8,"position":"往来井井，","text":"此本泰卦。阳往居五，得坎为井；阴来在下，亦为井，故“往来井井”也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":9,"position":"汔至亦未繘，","text":"汔至者，阴来居初下。至汔，竟也。繘者，所以出水通井道也。今乃在初，未得应五，故“未繘”也。繘得，绠汲之具也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":11,"position":"羸其瓶，是以凶也。","text":"井，谓二。瓶，谓初。初欲应五，今为二所拘羸，故“凶”也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":18,"position":"九三：井渫不食，为我心恻。","text":"渫去秽浊，清洁之意也，三者得正，故曰“井渫”。不得据阴，喻不得用，故曰“不食”。道既不行，故“我心恻”。","locator":{"book":"周易集解","gua":"井","pos":"九三"},"citation":"《周易集解》·井卦·九三","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":19,"position":"可用汲，王明，并受其福。","text":"谓五可用汲三，则王道明而天下并受其福。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":21,"position":"六四：井甃，无咎。","text":"坎性下降，嫌于从三。能自修正，以甃辅五。故“无咎”也。","locator":{"book":"周易集解","gua":"井","pos":"六四"},"citation":"《周易集解》·井卦·六四","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":12,"position":"六二：已日乃革之，征吉，无咎。","text":"日以喻君也。谓五已居位为君。二乃革意去三应五。故曰“已日乃革之”。上行应五，去卑事尊，故曰“征吉，无咎也”。","locator":{"book":"周易集解","gua":"革","pos":"六二"},"citation":"《周易集解》·革卦·六二","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":14,"position":"九三，征凶，贞厉。","text":"三应于上，欲往应之，为阴所乘故曰“征凶”。若正居三，而据二阴，则五来危之，故曰“贞厉”也。","locator":{"book":"周易集解","gua":"革","pos":"九三"},"citation":"《周易集解》·革卦·九三","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":1,"position":"：鼎，象也。以木巽火，亨饪也。","text":"震人离下，中有乾象。木火在外，金在其内，鼎镬亨饪之象也。","locator":{"book":"周易集解","gua":"鼎","pos":"象传"},"citation":"《周易集解》·鼎卦·象传","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":5,"position":"：木上有火，鼎。","text":"木火相因，金在其间。调和五味，所以养人。鼎之象也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":9,"position":"：鼎颠趾，未悖也。","text":"以阴承阳，故“未悖也”。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":6,"position":"日中则昃，","text":"丰者至盛，故“日中”。下居四，日昃之象也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":9,"position":"：雷电皆至，丰。","text":"丰者，阴据不正，夺阳之位而行以丰。故“折狱致刑”，以讨除之也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":4,"position":"：随风，巽。君子以申命行事。","text":"巽为号令，两巽相随，故“申命”也。法教百端，令行为上，贵其必从，故曰“行事”也。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":6,"position":"：进退，志疑也。","text":"风性动，进退欲承五，为二所据，故志以疑也。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":8,"position":"九二：巽在床下，","text":"床下，以喻近也。二者，军帅。三者，号令。故言“床下”。以明将之所专，不过军中事也。","locator":{"book":"周易集解","gua":"巽","pos":"九二"},"citation":"《周易集解》·巽卦·九二","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":9,"position":"用史巫纷若，吉，无咎。","text":"史以书勋，巫以告庙。纷，变。若，顺也。谓二以阳应阳，君所不臣，军师之象。征伐既毕，书勋告庙。当变而且顺五则吉。故曰“用史巫纷若，吉无咎”矣。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":10,"position":"：纷若之吉，得中也。","text":"谓二以处中和，故能变。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":12,"position":"：频巽之吝，志穷也。","text":"乘阳无据，为阴所乘，号令不行，故“志穷也”。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":19,"position":"丧其齐斧，贞凶。","text":"军罢师旋，亦告于庙，还斧于君，故“丧齐斧”。正如其故，不执臣节，则凶。故曰“丧其齐斧，贞凶”。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":2,"position":"：涣亨，刚来而不穷，柔得位乎外而上同。","text":"谓阳来居二，在坤之中，为立庙。假，大也。言受命之王，居五大位，上体之中，上享天帝，下立宗庙也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":4,"position":"：风行水上，涣。先王以享于帝，立庙。","text":"谓受命之王，收集散民，上享天帝，下立宗庙也。阴上至四承五，为享帝。阳下至二，为立庙也。离日上为宗庙，而谓天帝宗庙之神所配食者。王者所奉，故继于上。至于宗庙，其实在地。地者阴中之阳，有似庙中之神。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":9,"position":"六三：涣其躬，无悔。","text":"体中曰躬。谓涣三使承上，为志在外，故“无悔”。","locator":{"book":"周易集解","gua":"涣","pos":"六三"},"citation":"《周易集解》·涣卦·六三","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":15,"position":"涣王居，无咎。","text":"布其德教，王居其所，故“无咎”矣。《象》曰：王居无咎，正位也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":19,"position":"：苦节贞凶，其道穷也。","text":"乘阳于上，无应于下，故“其道穷也”。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":5,"position":"豚鱼吉：信及豚鱼也。","text":"豚鱼，谓四、三也。艮为山陆，豚所处。三为兑泽，鱼所在。豚者卑贱，鱼者幽隐，中信之道，皆及之矣。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":10,"position":"初九：虞吉，有它不燕。","text":"虞，安也。初应于四，宜自安虞；无意于四，则吉。故曰“虞吉”也。四者承五，有它意于四，则不安，故曰“有它不燕”也。","locator":{"book":"周易集解","gua":"中孚","pos":"初九"},"citation":"《周易集解》·中孚卦·初九","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":11,"position":"：初九虞吉，志未变也。","text":"初位潜藏，未得变而应四也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":14,"position":"六三：得敌，或鼓或罢，或泣或歌。","text":"三四俱阴，故称“得“也。四得位，有位。故鼓而歌。三失位，无实。故罢而泣之也。","locator":{"book":"周易集解","gua":"中孚","pos":"六三"},"citation":"《周易集解》·中孚卦·六三","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":3,"position":"：小过，小者过而亨也。过以利贞，与时行也","text":"阴称校谓四应初，过二而去。三应上，过五而去。五处中，见过不见应。故曰“小者过而亨也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":20,"position":"往厉必戒，勿用永贞。","text":"四往危五，戒备于三，故曰“往厉必戒”也。勿长居四，当动上五，故“用永贞”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":2,"position":"：既济亨，小者亨也。","text":"天地既交，阳升阴降，故“小者亨也”。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":6,"position":"：水在火上，既济。君子以思患而豫防之。","text":"六爻既正，必当复乱，故君子象之。思患而豫防之，治不忘乱也。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":17,"position":"：濡其首厉，何可久也。","text":"居上濡五，处高居盛，必当复危，故“何可久也”。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":2,"position":"：未济亨，柔得中也。","text":"柔上居五，与阳合同，故“亨”也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":5,"position":"虽不当位，刚柔应也。","text":"虽刚柔相应，而不以正，由未能济也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":12,"position":"六三：未济，征凶，利涉大川。","text":"未济者，未成也。女在外，男在内，婚姻未成。征上从四则凶。利下从坎，故“利涉大川”矣。","locator":{"book":"周易集解","gua":"未济","pos":"六三"},"citation":"《周易集解》·未济卦·六三","edition":"jijie"}],"zhezhongSamples":[{"gua":"剥","guaId":"g23","pos":"集说/总论","text":"众皆剥阳，三独应上，无剥害意，是以“无咎”。","locator":{"book":"周易折中","gua":"剥","pos":"总论"},"citation":"《御纂周易折中》·剥卦·总论","edition":"zhezhong"},{"gua":"蹇","guaId":"g39","pos":"集说/总论","text":"蹇难之世，不安其所，故曰“往蹇”也。来还承五，则与至尊相连，故曰“来连”也。","locator":{"book":"周易折中","gua":"蹇","pos":"总论"},"citation":"《御纂周易折中》·蹇卦·总论","edition":"zhezhong"},{"gua":"中孚","guaId":"g61","pos":"集说/总论","text":"“虞”，安也。初应于四，宜自安虞，无意于四则吉，故曰“虞吉”也，有意于四则不安，故曰“有它不燕”也。","locator":{"book":"周易折中","gua":"中孚","pos":"总论"},"citation":"《御纂周易折中》·中孚卦·总论","edition":"zhezhong"},{"gua":"未济","guaId":"g64","pos":"集说/总论","text":"木入水出，《井》之象也。","locator":{"book":"周易折中","gua":"未济","pos":"总论"},"citation":"《御纂周易折中》·未济卦·总论","edition":"zhezhong"},{"gua":"未济","guaId":"g64","pos":"集说/总论","text":"阳欲“无首”，阴以“大终”。","locator":{"book":"周易折中","gua":"未济","pos":"总论"},"citation":"《御纂周易折中》·未济卦·总论","edition":"zhezhong"}],"samples":[{"gua":"乾","guaId":"g01","pos":"九三：君子终日乾乾，夕惕，若厉，无咎。","text":"日以喻君。谓三居下体之终，而为之君，承乾行乾，故曰“乾乾”。夕惕以喻臣。谓三臣于五，则疾修柔顺，危去阳行，故曰“无咎”。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"},{"gua":"乾","guaId":"g01","pos":"万物资始，","text":"谓分为六十四卦，万一千五百二十册，皆受始于乾也。册取始于乾，犹万物之生禀于天。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"},{"gua":"乾","guaId":"g01","pos":"大明终始，","text":"乾起坎，而终于离。坤起于离，而终于坎。离坎者，乾坤之家，而阴阳之府，故曰“大明终始”也。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"}]};
